    #[test]
    fn init_segment_declares_avc_and_common_encryption() {
        let init = build_init_segment(&fixture_config(), Some([3u8; 16])).unwrap();

        for marker in [
            b"ftyp", b"moov", b"encv", b"avcC", b"sinf", b"cenc", b"tenc",
        ] {
            assert!(init.windows(4).any(|window| window == marker));
        }
        assert!(init.windows(16).any(|window| window == [3u8; 16]));

        let tenc = find_box(&init, *b"tenc").unwrap();
        assert_eq!(
            &init[tenc + 8..tenc + 16],
            &[0, 0, 0, 0, 0, 0, 1, 16],
            "version/flags, reserved, pattern, protected, and IV-size fields"
        );
    }

    #[test]
    fn media_fragment_encrypts_nal_payload_but_not_length_or_header() {
        let access_unit = [
            0, 0, 0, 1, 0x65, 1, 2, 3, 4, 5, 6, 7, 8, 0, 0, 1, 0x06, 9, 10, 11,
        ];
        let fragment = build_fragment(
            Some(&[4u8; 16]),
            FragmentInput {
                sequence: 1,
                decode_time: 0,
                duration: 90_000,
                keyframe: true,
                annex_b: &access_unit,
                iv: [5u8; 16],
            },
        )
        .unwrap();

        assert_eq!(&fragment.encrypted_sample[..5], &[0, 0, 0, 9, 0x65]);
        assert_ne!(&fragment.encrypted_sample[5..13], &[1, 2, 3, 4, 5, 6, 7, 8]);
        assert_eq!(fragment.subsamples.len(), 2);
        for marker in [
            b"moof", b"traf", b"trun", b"senc", b"saiz", b"saio", b"mdat",
        ] {
            assert!(fragment.bytes.windows(4).any(|window| window == marker));
        }
    }

    #[test]
    fn mpd_declares_cenc_timeline_and_epoch_paths() {
        let stream = Uuid::from_u128(1);
        let epoch = Uuid::from_u128(2);
        let mpd = build_mpd(&MpdConfig {
            stream_id: stream,
            epoch_id: epoch,
            key_id: *epoch.as_bytes(),
            width: 1280,
            height: 720,
            codec: "avc1.42c01f",
            availability_start_time: "2026-01-01T00:00:00Z",
            time_shift_buffer_depth_seconds: 1800,
            segments: &[
                SegmentTimelineEntry {
                    number: 7,
                    start: 0,
                    duration: 360_000,
                },
                SegmentTimelineEntry {
                    number: 8,
                    start: 360_000,
                    duration: 360_000,
                },
            ],
            dynamic: true,
        });

        assert!(mpd.contains("type=\"dynamic\""));
        assert!(mpd.contains("value=\"cenc\""));
        assert!(mpd.contains(&format!("cenc:default_KID=\"{epoch}\"")));
        assert!(mpd.contains("startNumber=\"7\""));
        assert!(mpd.contains("<S t=\"360000\" d=\"360000\"/>"));

        let static_segments = [
            SegmentTimelineEntry {
                number: 7,
                start: 360_000,
                duration: 360_000,
            },
            SegmentTimelineEntry {
                number: 8,
                start: 720_000,
                duration: 360_000,
            },
        ];
        let static_mpd = build_mpd(&MpdConfig {
            stream_id: stream,
            epoch_id: epoch,
            key_id: *epoch.as_bytes(),
            width: 1280,
            height: 720,
            codec: "avc1.42c01f",
            availability_start_time: "2026-01-01T00:00:00Z",
            time_shift_buffer_depth_seconds: 1800,
            segments: &static_segments,
            dynamic: false,
        });
        assert!(static_mpd.contains("type=\"static\""));
        assert!(static_mpd.contains("mediaPresentationDuration=\"PT8.000S\""));
        assert!(static_mpd.contains("presentationTimeOffset=\"360000\""));
        assert!(!static_mpd.contains("availabilityStartTime"));
    }

    #[test]
    fn object_authentication_detects_header_and_payload_changes() {
        let key = [11u8; 32];
        let tag = authenticate_object(&key, b"header", b"payload");

        assert!(verify_object_authentication(
            &key, b"header", b"payload", &tag
        ));
        assert!(!verify_object_authentication(
            &key, b"other", b"payload", &tag
        ));
        assert!(!verify_object_authentication(
            &key, b"header", b"other", &tag
        ));
    }
    #[test]
    fn every_byte_of_a_sample_is_covered_by_the_subsample_table() {
        // CENC requires the subsample table to account for the whole sample:
        // each entry is (clear, encrypted) and the sum must equal its length.
        // A decoder handed a table that stops short has no defined way to read
        // the rest, which is why this fails silently rather than loudly.
        let key = [7u8; 16];
        let cases: &[(&str, &[u8])] = &[
            (
                "ordinary slice",
                &[0, 0, 0, 1, 0x65, 1, 2, 3, 4, 5, 6, 7, 8],
            ),
            // A one-byte NAL: an end-of-sequence or end-of-stream marker is
            // exactly this, and a static picture is where an encoder emits the
            // smallest units it has.
            (
                "one-byte NAL present",
                &[0, 0, 0, 1, 0x65, 9, 9, 9, 0, 0, 0, 1, 0x0a],
            ),
        ];
        for (name, annex_b) in cases {
            let fragment = build_fragment(
                Some(&key),
                FragmentInput {
                    sequence: 1,
                    decode_time: 0,
                    duration: 3000,
                    keyframe: true,
                    annex_b,
                    iv: [1u8; 16],
                },
            )
            .unwrap_or_else(|error| panic!("{name}: {error}"));
            let covered: usize = fragment
                .subsamples
                .iter()
                .map(|s| usize::from(s.clear_bytes) + s.encrypted_bytes as usize)
                .sum();
            assert_eq!(
                covered,
                fragment.encrypted_sample.len(),
                "{name}: subsample table covers {covered} of {} sample bytes",
                fragment.encrypted_sample.len()
            );
        }
    }
